<template>
  <section class="mx-auto flex min-h-[calc(100vh-4rem)] max-w-xl items-center px-4 py-16 sm:px-6"><div class="w-full border-y py-10"><ShieldCheck class="h-9 w-9 text-primary" aria-hidden="true" /><h1 class="display-face mt-5 text-4xl font-semibold">Set a new password</h1><form class="mt-8 space-y-5" @submit.prevent="submit"><div><label class="field-label" for="identifier">Email, username, or phone</label><Input id="identifier" v-model.trim="form.identifier" required /></div><div><label class="field-label" for="code">Six-digit reset code</label><Input id="code" v-model.trim="form.code" inputmode="numeric" maxlength="6" required /></div><div><label class="field-label" for="new-password">New password</label><Input id="new-password" v-model="form.new_password" type="password" autocomplete="new-password" minlength="10" required /></div><p v-if="message" class="text-sm" :class="complete ? 'text-primary' : 'text-destructive'" aria-live="polite">{{ message }}</p><Button v-if="!complete" class="min-h-12 w-full" :disabled="loading">{{ loading ? 'Updating…' : 'Update password' }}</Button><ButtonLink v-else to="/login" class="min-h-12 w-full">Return to sign in</ButtonLink></form></div></section>
</template>
<script setup>
import { ShieldCheck } from 'lucide-vue-next'
const auth = useAuthStore(); const route = useRoute(); const form = reactive({ identifier: String(route.query.identifier || ''), code: '', new_password: '' }); const message = ref(''); const loading = ref(false); const complete = ref(false)
async function submit() { loading.value = true; message.value = ''; try { const response = await auth.resetPassword(form); message.value = response.message; complete.value = true } catch (error) { message.value = error?.data?.error?.message || 'The password could not be updated.' } finally { loading.value = false } }
</script>
